// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait FlowStatusDeterminer_Api {
  def id: Art.BridgeId
  def decisionReason_Id : Art.PortId
  def appliedSnapshot_Id : Art.PortId
  def flowStatus_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var flowStatus: Factory_Flow.ProductionFlowStatus.Type = $

  def put_flowStatus(value : Factory_Flow.ProductionFlowStatus.Type) : Unit = {
    Contract(
      Modifies(flowStatus),
      Ensures(
        flowStatus == value
      )
    )
    Spec {
      flowStatus = value
    }

    Art.putValue(flowStatus_Id, Factory_Flow.ProductionFlowStatus_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class FlowStatusDeterminer_Initialization_Api (
  val id: Art.BridgeId,
  val decisionReason_Id : Art.PortId,
  val appliedSnapshot_Id : Art.PortId,
  val flowStatus_Id : Art.PortId) extends FlowStatusDeterminer_Api

@datatype class FlowStatusDeterminer_Operational_Api (
  val id: Art.BridgeId,
  val decisionReason_Id : Art.PortId,
  val appliedSnapshot_Id : Art.PortId,
  val flowStatus_Id : Art.PortId) extends FlowStatusDeterminer_Api {

  // Logika spec var representing port state for incoming data port
  @spec var decisionReason: Factory_Flow.DecisionReason.Type = $

  def get_decisionReason() : Option[Factory_Flow.DecisionReason.Type] = {
    Contract(
      Ensures(
        Res == Some(decisionReason)
      )
    )
    val value : Option[Factory_Flow.DecisionReason.Type] = Art.getValue(decisionReason_Id) match {
      case Some(Factory_Flow.DecisionReason_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port decisionReason.  Expecting 'Factory_Flow.DecisionReason_Payload' but received ${v}")
        None[Factory_Flow.DecisionReason.Type]()
      case _ => None[Factory_Flow.DecisionReason.Type]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var appliedSnapshot: Factory_Flow.FlowSnapshot = $

  def get_appliedSnapshot() : Option[Factory_Flow.FlowSnapshot] = {
    Contract(
      Ensures(
        Res == Some(appliedSnapshot)
      )
    )
    val value : Option[Factory_Flow.FlowSnapshot] = Art.getValue(appliedSnapshot_Id) match {
      case Some(Factory_Flow.FlowSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port appliedSnapshot.  Expecting 'Factory_Flow.FlowSnapshot_Payload' but received ${v}")
        None[Factory_Flow.FlowSnapshot]()
      case _ => None[Factory_Flow.FlowSnapshot]()
    }
    return value
  }
}
